const { readFileSync, statSync } = await import('node:fs');
const path = process.env.NOTE_PATH;
if (!path) throw new Error('NOTE_PATH env var missing');
try { statSync(path); } catch (e) { throw new Error(`File not found: ${path}`); }
globalThis.notePath = path;

const { readFileSync } = await import('node:fs');
const buffer = readFileSync(globalThis.notePath);
const mod = await import('supernote-typescript');
const { SupernoteX, toPdf } = mod;
const note = new SupernoteX(buffer);
const pdfBytes = await toPdf(note);
globalThis.pdfBytes = pdfBytes;
